-- ============================================================
-- CodeQuest Database Setup
-- MySQL 8.0+
-- Import this file using MySQL Workbench or:
-- mysql -u root -p < codequest_db.sql
--
-- NOTE:
-- 1. This script creates the schema and the eight default courses.
-- 2. It intentionally does NOT create a student or admin account.
--    Passwords in CodeQuest are stored as PBKDF2 hashes generated by
--    PasswordUtil.java. Do not store plain-text passwords here.
-- 3. Existing lesson and mission content can be added through the
--    CodeQuest Admin Dashboard after the admin account is provisioned.
-- ============================================================

CREATE DATABASE IF NOT EXISTS codequest_db
    CHARACTER SET utf8mb4
    COLLATE utf8mb4_unicode_ci;

USE codequest_db;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS mission_submissions;
DROP TABLE IF EXISTS lesson_progress;
DROP TABLE IF EXISTS lessons;
DROP TABLE IF EXISTS missions;
DROP TABLE IF EXISTS courses;
DROP TABLE IF EXISTS admins;
DROP TABLE IF EXISTS users;

SET FOREIGN_KEY_CHECKS = 1;

-- ------------------------------------------------------------
-- 1. STUDENTS
-- ------------------------------------------------------------
CREATE TABLE users (
    user_id INT NOT NULL AUTO_INCREMENT,
    username VARCHAR(50) NOT NULL,
    email VARCHAR(100) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    xp INT NOT NULL DEFAULT 0,
    level INT NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_users_username (username),
    UNIQUE KEY uq_users_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 2. ADMINS
-- ------------------------------------------------------------
CREATE TABLE admins (
    admin_id INT NOT NULL AUTO_INCREMENT,
    username VARCHAR(50) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    PRIMARY KEY (admin_id),
    UNIQUE KEY uq_admins_username (username)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 3. COURSES
-- ------------------------------------------------------------
CREATE TABLE courses (
    course_id INT NOT NULL AUTO_INCREMENT,
    title VARCHAR(100) NOT NULL,
    description TEXT,
    category VARCHAR(50) NOT NULL,
    difficulty VARCHAR(30) NOT NULL DEFAULT 'Beginner',
    duration VARCHAR(50) DEFAULT '4 Weeks',
    is_active TINYINT(1) NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (course_id),
    UNIQUE KEY uq_courses_title (title)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 4. LESSONS
-- ------------------------------------------------------------
CREATE TABLE lessons (
    lesson_id INT NOT NULL AUTO_INCREMENT,
    course_id INT NOT NULL,
    title VARCHAR(150) NOT NULL,
    content TEXT,
    code_example TEXT,
    output_example TEXT,
    lesson_order INT NOT NULL DEFAULT 1,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (lesson_id),
    UNIQUE KEY uq_course_lesson_order (course_id, lesson_order),
    CONSTRAINT fk_lessons_course
        FOREIGN KEY (course_id) REFERENCES courses(course_id)
        ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 5. LESSON PROGRESS
-- ------------------------------------------------------------
CREATE TABLE lesson_progress (
    progress_id INT NOT NULL AUTO_INCREMENT,
    user_id INT NOT NULL,
    lesson_id INT NOT NULL,
    completed TINYINT(1) NOT NULL DEFAULT 0,
    completed_at TIMESTAMP NULL DEFAULT NULL,
    PRIMARY KEY (progress_id),
    UNIQUE KEY uq_user_lesson (user_id, lesson_id),
    KEY idx_lesson_progress_lesson (lesson_id),
    CONSTRAINT fk_progress_user
        FOREIGN KEY (user_id) REFERENCES users(user_id)
        ON DELETE CASCADE,
    CONSTRAINT fk_progress_lesson
        FOREIGN KEY (lesson_id) REFERENCES lessons(lesson_id)
        ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 6. MISSIONS
-- ------------------------------------------------------------
CREATE TABLE missions (
    mission_id INT NOT NULL AUTO_INCREMENT,
    title VARCHAR(150) NOT NULL,
    description TEXT NOT NULL,
    category VARCHAR(50) NOT NULL,
    difficulty VARCHAR(30) NOT NULL DEFAULT 'Easy',
    option_a VARCHAR(500) NOT NULL,
    option_b VARCHAR(500) NOT NULL,
    option_c VARCHAR(500) NOT NULL,
    option_d VARCHAR(500) NOT NULL,
    correct_answer CHAR(1) NOT NULL,
    xp_reward INT NOT NULL DEFAULT 10,
    PRIMARY KEY (mission_id),
    CONSTRAINT chk_mission_answer
        CHECK (correct_answer IN ('A', 'B', 'C', 'D')),
    CONSTRAINT chk_mission_xp
        CHECK (xp_reward >= 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- 7. MISSION SUBMISSIONS
-- ------------------------------------------------------------
CREATE TABLE mission_submissions (
    submission_id INT NOT NULL AUTO_INCREMENT,
    user_id INT NOT NULL,
    mission_id INT NOT NULL,
    selected_answer CHAR(1) NOT NULL,
    is_correct TINYINT(1) NOT NULL DEFAULT 0,
    submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (submission_id),
    UNIQUE KEY uq_user_mission (user_id, mission_id),
    KEY idx_submission_mission (mission_id),
    CONSTRAINT fk_submission_user
        FOREIGN KEY (user_id) REFERENCES users(user_id)
        ON DELETE CASCADE,
    CONSTRAINT fk_submission_mission
        FOREIGN KEY (mission_id) REFERENCES missions(mission_id)
        ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

