-- DSA stack lesson known to be added as lesson order 11.
-- It is inserted only if that course/order does not already exist.
INSERT INTO lessons (course_id, title, content, lesson_order)
SELECT c.course_id,
       'Stack Data Structure',
       'A stack is a linear data structure that follows the LIFO (Last In, First Out) principle.',
       11
FROM courses c
WHERE c.title = 'DSA'
  AND NOT EXISTS (
      SELECT 1
      FROM lessons l
      WHERE l.course_id = c.course_id
        AND l.lesson_order = 11
  );

-- ------------------------------------------------------------
-- VERIFICATION QUERIES
-- ------------------------------------------------------------
SELECT 'users' AS table_name, COUNT(*) AS total_rows FROM users
UNION ALL
SELECT 'admins', COUNT(*) FROM admins
UNION ALL
SELECT 'courses', COUNT(*) FROM courses
UNION ALL
SELECT 'lessons', COUNT(*) FROM lessons
UNION ALL
SELECT 'lesson_progress', COUNT(*) FROM lesson_progress
UNION ALL
SELECT 'missions', COUNT(*) FROM missions
UNION ALL
SELECT 'mission_submissions', COUNT(*) FROM mission_submissions;

SELECT course_id, title, category, difficulty, duration
FROM courses
ORDER BY course_id;
